import re
from decimal import Decimal

_MAX_CENTS = 100000000  # 1000000.00
_PATTERN = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")


def _to_cents(value):
    """Validate value and return exact integer number of cents (> 0)."""
    if isinstance(value, bool):
        raise ValueError("invalid amount")
    if isinstance(value, str):
        if not _PATTERN.fullmatch(value):
            raise ValueError("invalid amount")
        value = Decimal(value)  # construction is exact, ignores context
    elif isinstance(value, int):
        value = Decimal(value)
    elif not isinstance(value, Decimal):
        raise ValueError("invalid amount")
    if not value.is_finite():
        raise ValueError("invalid amount")
    # Comparisons are exact and independent of context precision.
    if value <= 0 or value > Decimal(_MAX_CENTS) / 100:
        raise ValueError("amount out of range")
    sign, digits, exp = value.as_tuple()
    n = int("".join(map(str, digits)))
    if exp >= -2:
        n *= 10 ** (exp + 2)
    else:
        shift = -2 - exp
        # Avoid huge powers: reject if more than `shift` digits can't be dropped.
        if shift > len(digits):
            raise ValueError("not representable in cents")
        q, r = divmod(n, 10 ** shift)
        if r:
            raise ValueError("not representable in cents")
        n = q
    if n <= 0 or n > _MAX_CENTS:
        raise ValueError("amount out of range")
    return n


def _from_cents(n):
    return Decimal((0, tuple(int(c) for c in str(n)), -2)) if n else Decimal((0, (0,), -2))


def parse_amount(value):
    return _from_cents(_to_cents(value))


def format_amount(value):
    return format(value, ".2f")
EOF
