from .money import parse_amount, format_amount, _to_cents, _from_cents, _MAX_CENTS


def make_invoice(amounts):
    if type(amounts) is not list:
        raise ValueError("amounts must be a list")
    total = 0
    for item in amounts:
        total += _to_cents(item)
        if total > _MAX_CENTS:
            raise ValueError("total too large")
    return {"total": format_amount(_from_cents(total)), "count": len(amounts)}
